-- NULL. Sans elles, la page reste vide meme apres un import reussi.
-- =============================================================================


-- 1. SAUVEGARDE — lis cette sortie avant de continuer
select * from prop_firms where slug = 'ftmo';
select * from prop_firm_challenges where firm_slug = 'ftmo';


-- 2. Colonnes necessaires (sans effet si elles existent deja)
alter table prop_firms add column if not exists price_currency text default 'USD';
alter table prop_firms add column if not exists data_verified_at timestamptz;
alter table prop_firms add column if not exists data_verified_by text;
alter table prop_firms add column if not exists source_url text;
alter table prop_firms add column if not exists rating_checked_at timestamptz;
alter table prop_firms add column if not exists discount_status text;
alter table prop_firms add column if not exists discount_starts_at timestamptz;
alter table prop_firms add column if not exists max_profit_split integer;
alter table prop_firms add column if not exists translations jsonb;
alter table prop_firms add column if not exists restricted_countries text[];


-- 3. La firme : identite, contenu editorial, listes
update prop_firms set
  name                 = 'FTMO',
  founded_year         = 2015,
  headquarters         = 'Quadrio Offices, Purkyňova 2121/3, 110 00 Prague, Czech Republic',
  country              = 'Czech Republic',
  price_currency       = 'EUR',
  is_regulated         = false,
  regulation_details   = 'FTMO Evaluation Global s.r.o.; the contracting entity can vary by region. Neither a broker nor an investment firm: the service runs on simulated accounts and takes no client deposits.',
  trustpilot_rating    = 4.8,
  min_price            = 79,
  max_price            = 1080,
  profit_split         = 80,
  max_profit_split     = 90,
  max_allocation       = 'Up to $400,000 initial allocation, and up to $2,000,000 through the Scaling Plan',
  is_futures           = false,
  drawdown_type        = 'Daily loss measured on equity and reset at midnight CE(S)T. Overall drawdown trails end-of-day on the 1-Step and locks once it reaches the starting balance; fixed on the 2-Step.',
  time_limit           = 'No time limit, on either product',
  payout_frequency     = 'on request, no earlier than 14 days after your first trade',
  source_url           = 'https://ftmo.com/en/trading-objectives/',
  platforms            = 'MetaTrader 4, MetaTrader 5, cTrader, TradingView',
  assets               = '{"Forex CFDs","Metals","Indices","Energies","Crypto","Commodities","Stock CFDs"}'::text[],
  payout_methods       = '{"Bank transfer","Other methods shown in the Client Area, where available"}'::text[],
  included_items       = '{"MetaTrader 4, MetaTrader 5, cTrader and TradingView","FTMO dashboard and performance metrics","No activation fee on the funded account"}'::text[],
  pros                 = '{"Trading since 2015, one of the longest track records in the sector","90% split on the 1-Step, the higher of the two products","No time limit, on either the 1-Step or the 2-Step","The 1-Step sets no fixed minimum trading days","On the 2-Step, the fee comes back in full with your first reward","The Swing account lifts news, overnight and weekend restrictions","Allocation up to $400,000, and up to $2,000,000 through the Scaling Plan","Priced in euros, from €79"}'::text[],
  cons                 = '{"No resets: after a failure you buy a whole new challenge","The fee refund is not advertised on the 1-Step","The 1-Step tightens the daily limit to 3% and uses a trailing drawdown","The 2-Step requires 4 trading days in each phase","The funded Standard account restricts news, overnight and weekend holding","Swing does not exist on the 1-Step and caps leverage at 1:30","Swing offers no 200K account"}'::text[],
  special_features     = '{"Two products with genuinely different rules","1-Step: 3% daily loss, trailing drawdown that locks at the starting balance","2-Step: 5% daily loss, fixed drawdown","The Best Day Rule applies to the 1-Step only","Leverage up to 1:100 on Standard, 1:30 on Swing","Scaling Plan: +25% balance every 4 months, on the 2-Step only","No mandatory stop-loss","Pay by card, bank wire, PayPal, Skrill, crypto and Revolut Pay; Apple Pay and Google Pay where available"}'::text[],
  verdict_card         = '{"title":"Who it suits, and who it does not","body":"FTMO sells two products worth telling apart before you buy. The 1-Step pays more — 90% — and sets no calendar, but tightens the screws day to day. The 2-Step pays 80%, leaves more daily room, and refunds the fee with your first reward.","points":["The best split with no strings: 90% from your first reward on the 1-Step","Getting the fee back: the 2-Step refunds it in full with the first reward","A comfortable daily limit: 5% on the 2-Step against 3% on the 1-Step","The freedom to hold positions overnight and over the weekend, with Swing","An allocation that reaches $2,000,000 through the Scaling Plan"]}'::jsonb,
  program_guide        = '{"title":"Three routes, three trade-offs","intro":"All three lead to a funded account. The choice turns on the split, the calendar, and how freely you can hold positions.","options":[{"name":"1-Step","badge":"Single phase","summary":"The highest split, 90%, and no minimum days. In exchange, a 3% daily limit and a drawdown that follows your highs.","points":["10% target, 90% split","3% daily loss","Trailing drawdown, locked at the starting balance","Best day ≤ 50% of the profit from winning days","From €79 (10K) to €999 (200K)"]},{"name":"2-Step Standard","badge":"Two phases","summary":"10% then 5% targets, a wider 5% daily limit and a fixed drawdown. The fee is refunded with your first reward.","points":["10% then 5% target, 80% split","5% daily loss, fixed drawdown","4 minimum trading days per phase","Fee refunded in full at the first reward","From €89 (10K) to €1,080 (200K)"]},{"name":"2-Step Swing","badge":"Hold positions","summary":"The 2-Step rules with no news, overnight or weekend restrictions, funded account included. Leverage drops to 1:30 and there is no 200K.","points":["Same targets and limits as the 2-Step Standard","News, overnight and weekend free, even once funded","Leverage capped at 1:30","From €99 (10K) to €599 (100K)"]}]}'::jsonb,
  key_rules            = '{"title":"The rules that decide it","intro":"Five points most comparison sites get wrong.","rules":[{"title":"The split depends on the product","detail":"90% on the 1-Step, unconditionally. 80% on the 2-Step, rising to 90% through the Scaling Plan. Pages that advertise \"up to 90%\" across the range hide the fact that the 1-Step starts there."},{"title":"Only the 2-Step refunds the fee","detail":"The 2-Step returns 100% of the challenge price with your first reward. On the 1-Step, FTMO advertises no refund. Cheaper on the sticker, the 1-Step therefore costs more once you are funded."},{"title":"The daily loss differs, and is measured on equity","detail":"3% on the 1-Step, 5% on the 2-Step. It is measured on equity — floating losses, commissions and swaps included — and resets at midnight CE(S)T, not in your own time zone."},{"title":"The 1-Step drawdown trails, then locks","detail":"It rises with your highest closing balance, then stops for good once it reaches the starting balance. The 2-Step is on a fixed drawdown from the first trade."},{"title":"There is no reset","detail":"A failed challenge cannot be restarted at a discount: you buy a whole new one. That is a real cost difference against firms charging 50% for a reset."}],"more":["No time limit on any of the three routes","No fixed minimum days on the 1-Step; 4 per phase on the 2-Step","No activation fee on the funded account","No mandatory stop-loss","Leverage up to 1:100 on Standard, 1:30 on Swing","Scaling Plan: +25% balance every 4 months, on the 2-Step","MT4, MT5, cTrader and TradingView"]}'::jsonb,
  journey              = '{"title":"What happens after you pay","intro":"The route differs by product.","steps":[{"title":"Evaluation","detail":"One phase on the 1-Step, two on the 2-Step. No restriction on news, overnight or weekend positions at this stage, whichever product you picked."},{"title":"Verification","detail":"On the 2-Step only: a second 5% target, under the same risk limits as the first phase."},{"title":"FTMO Account","detail":"Standard restricts news and requires closing before market breaks over 2 hours and before the weekend. Swing restricts nothing. Swing does not exist on the 1-Step."},{"title":"Rewards","detail":"The first cannot be requested before 14 days; after that you choose your reward day. On the 2-Step, that first reward also refunds the challenge price."}]}'::jsonb,
  cost_timeline        = '{"title":"What you will pay","intro":"The costs do not all land at the same moment — and some of it comes back.","steps":[{"label":"At purchase","title":"One-off fee","detail":"From €79 for a 1-Step 10K to €1,080 for a 2-Step 200K. No subscription."},{"label":"On failure","title":"No reset available","detail":"FTMO does not sell discounted resets: starting over means buying a whole new challenge."},{"label":"On passing","title":"No activation fee","detail":"The funded account opens with no further payment."},{"label":"At the first reward","title":"Refund on the 2-Step","detail":"The 2-Step returns 100% of the challenge price with the first reward. The 1-Step advertises no refund."}]}'::jsonb,
  translations         = '{"fr":{"headquarters":"Bureaux Quadrio, Purkyňova 2121/3, 110 00 Prague, République tchèque","regulation_details":"FTMO Evaluation Global s.r.o. ; l’entité contractante peut varier selon la région. Ni courtier ni entreprise d’investissement : le service repose sur des comptes simulés et n’accepte aucun dépôt de client.","max_allocation":"Jusqu’à 400 000 $ d’allocation initiale, et jusqu’à 2 000 000 $ via le plan de scaling","drawdown_type":"Perte journalière calculée sur l’equity et remise à zéro à minuit CE(S)T. Drawdown global glissant en fin de journée sur le 1-Step, verrouillé une fois arrivé au solde de départ ; fixe sur le 2-Step.","time_limit":"Aucune limite de temps, sur les deux produits","payout_frequency":"sur demande, au plus tôt 14 jours après le premier trade","assets":["CFD sur forex","Métaux","Indices","Énergie","Crypto","Matières premières","CFD sur actions"],"payout_methods":["Virement bancaire","Autres moyens affichés dans l’espace client, selon disponibilité"],"included_items":["MetaTrader 4, MetaTrader 5, cTrader et TradingView","Tableau de bord FTMO et métriques de performance","Aucun frais d’activation du compte financé"],"pros":["En activité depuis 2015, l’un des plus longs historiques du secteur","Partage de 90 % sur le 1-Step, le plus élevé des deux produits","Aucune limite de temps, ni sur le 1-Step ni sur le 2-Step","Le 1-Step n’impose aucun jour de trading minimum fixe","Sur le 2-Step, les frais sont remboursés à 100 % avec la première récompense","Le compte Swing lève les restrictions d’actualités, de nuit et de week-end","Allocation jusqu’à 400 000 $, et jusqu’à 2 000 000 $ via le plan de scaling","Prix en euros, à partir de 79 €"],"cons":["Aucun reset : après un échec, il faut racheter un challenge entier","Le remboursement des frais n’est pas annoncé sur le 1-Step","Le 1-Step serre la limite journalière à 3 % et utilise un drawdown glissant","Le 2-Step exige 4 jours de trading dans chaque phase","Le compte financé Standard restreint les annonces, la nuit et le week-end","Swing n’existe pas sur le 1-Step et plafonne le levier à 1:30","Le Swing ne propose pas de compte 200K"],"special_features":["Deux produits aux règles réellement différentes","1-Step : perte journalière de 3 %, drawdown glissant verrouillé au solde de départ","2-Step : perte journalière de 5 %, drawdown fixe","La règle du meilleur jour ne s’applique qu’au 1-Step","Levier jusqu’à 1:100 en Standard, 1:30 en Swing","Plan de scaling : +25 % de solde tous les 4 mois, sur le 2-Step uniquement","Aucune obligation de stop-loss","Paiement par carte, virement, PayPal, Skrill, crypto et Revolut Pay ; Apple Pay et Google Pay selon disponibilité"],"verdict_card":{"title":"Pour qui, et pour qui pas","body":"FTMO vend deux produits qu’il faut distinguer avant d’acheter. Le 1-Step paie mieux — 90 % — et n’impose pas de calendrier, mais serre la vis au quotidien. Le 2-Step paie 80 %, laisse plus de marge chaque jour, et rembourse les frais à la première récompense.","points":["Le meilleur partage sans condition : 90 % dès la première récompense sur le 1-Step","Récupérer le prix du challenge : le 2-Step le rembourse à 100 % avec la première récompense","Une limite journalière confortable : 5 % sur le 2-Step, contre 3 % sur le 1-Step","La liberté de garder vos positions la nuit et le week-end, avec le compte Swing","Une allocation qui monte à 2 000 000 $ via le plan de scaling"]},"program_guide":{"title":"Trois parcours, trois compromis","intro":"Les trois mènent à un compte financé. Le choix se joue sur le partage, le calendrier et la liberté de tenir vos positions.","options":[{"name":"1-Step","badge":"Une seule phase","summary":"Le partage le plus élevé, 90 %, et aucun jour minimum. En échange, une limite journalière de 3 % et un drawdown qui suit vos plus hauts.","points":["Objectif de 10 %, partage de 90 %","Perte journalière de 3 %","Drawdown glissant, verrouillé au solde de départ","Meilleur jour ≤ 50 % du profit des jours positifs","De 79 € (10K) à 999 € (200K)"]},{"name":"2-Step Standard","badge":"Deux phases","summary":"Objectif de 10 % puis 5 %, une limite journalière plus large à 5 % et un drawdown fixe. Les frais sont remboursés avec la première récompense.","points":["Objectif de 10 % puis 5 %, partage de 80 %","Perte journalière de 5 %, drawdown fixe","4 jours de trading minimum par phase","Frais remboursés à 100 % à la première récompense","De 89 € (10K) à 1 080 € (200K)"]},{"name":"2-Step Swing","badge":"Positions tenues","summary":"Les règles du 2-Step, sans aucune restriction d’actualités, de nuit ni de week-end, y compris une fois financé. Le levier tombe à 1:30 et le 200K n’existe pas.","points":["Mêmes objectifs et mêmes limites que le 2-Step Standard","Annonces, nuit et week-end libres, même sur le compte financé","Levier plafonné à 1:30","De 99 € (10K) à 599 € (100K)"]}]},"key_rules":{"title":"Les règles qui décident","intro":"Cinq points que la plupart des comparateurs rapportent mal.","rules":[{"title":"Le partage dépend du produit","detail":"90 % sur le 1-Step, sans condition. 80 % sur le 2-Step, porté à 90 % via le plan de scaling. Les pages qui annoncent « jusqu’à 90 % » pour toute la gamme masquent le fait que le 1-Step y arrive d’emblée."},{"title":"Les frais ne sont remboursés que sur le 2-Step","detail":"Le 2-Step rembourse 100 % du prix du challenge avec la première récompense. Sur le 1-Step, FTMO n’annonce pas de remboursement. À prix affiché plus bas, le 1-Step revient donc plus cher une fois financé."},{"title":"La perte journalière diffère, et se calcule sur l’equity","detail":"3 % sur le 1-Step, 5 % sur le 2-Step. Elle porte sur l’equity — donc pertes latentes, commissions et swaps compris — et se remet à zéro à minuit CE(S)T, pas à l’heure de votre fuseau."},{"title":"Le drawdown du 1-Step glisse, puis se verrouille","detail":"Il monte avec votre plus haut solde de clôture, puis s’arrête définitivement une fois arrivé au solde de départ. Le 2-Step est en drawdown fixe dès le premier trade."},{"title":"Il n’existe aucun reset","detail":"Un challenge échoué ne se relance pas à prix réduit : il faut en racheter un entier. C’est une différence de coût réel importante avec les firmes qui facturent 50 % pour un reset."}],"more":["Aucune limite de temps sur les trois parcours","Aucun jour minimum fixe sur le 1-Step ; 4 jours par phase sur le 2-Step","Aucun frais d’activation du compte financé","Aucune obligation de stop-loss","Levier jusqu’à 1:100 en Standard, 1:30 en Swing","Plan de scaling : +25 % de solde tous les 4 mois, sur le 2-Step","Plateformes MT4, MT5, cTrader et TradingView"]},"journey":{"title":"Ce qui se passe après le paiement","intro":"Le parcours diffère selon le produit choisi.","steps":[{"title":"Évaluation","detail":"Une phase sur le 1-Step, deux sur le 2-Step. Aucune restriction sur les annonces, les positions de nuit ou de week-end à ce stade, quel que soit le produit."},{"title":"Vérification","detail":"Uniquement sur le 2-Step : un second objectif de 5 %, avec les mêmes limites de risque que la première phase."},{"title":"Compte FTMO","detail":"Le Standard restreint les annonces et impose de fermer avant les coupures de marché de plus de 2 heures et avant le week-end. Le Swing ne restreint rien. Swing n’existe pas sur le 1-Step."},{"title":"Récompenses","detail":"La première ne peut pas être demandée avant 14 jours ; ensuite vous choisissez votre jour de récompense. Sur le 2-Step, cette première récompense rembourse aussi le prix du challenge."}]},"cost_timeline":{"title":"Ce que vous paierez","intro":"Les coûts n’arrivent pas tous au même moment — et une partie revient.","steps":[{"label":"À l’achat","title":"Frais unique","detail":"De 79 € pour un 10K en 1-Step à 1 080 € pour un 200K en 2-Step. Aucun abonnement."},{"label":"En cas d’échec","title":"Aucun reset possible","detail":"FTMO ne vend pas de reset à prix réduit : recommencer signifie racheter un challenge entier."},{"label":"À la validation","title":"Aucun frais d’activation","detail":"Le compte financé s’ouvre sans paiement supplémentaire."},{"label":"À la première récompense","title":"Remboursement sur le 2-Step","detail":"Le 2-Step rend 100 % du prix du challenge avec la première récompense. Le 1-Step n’annonce pas de remboursement."}]}},"de":{"headquarters":"Quadrio Offices, Purkyňova 2121/3, 110 00 Prag, Tschechien","regulation_details":"FTMO Evaluation Global s.r.o.; die vertragsschließende Gesellschaft kann je nach Region abweichen. Weder Broker noch Wertpapierfirma: Der Dienst läuft auf simulierten Konten und nimmt keine Kundeneinlagen entgegen.","max_allocation":"Bis zu 400.000 $ Anfangsallokation und bis zu 2.000.000 $ über den Scaling Plan","drawdown_type":"Tagesverlust auf Equity-Basis, Rücksetzung um Mitternacht CE(S)T. Der Gesamt-Drawdown läuft beim 1-Step am Tagesende nach und friert ein, sobald er den Startsaldo erreicht; beim 2-Step ist er fix.","time_limit":"Keine Zeitbegrenzung, bei beiden Produkten","payout_frequency":"auf Anfrage, frühestens 14 Tage nach dem ersten Trade","assets":["Forex-CFDs","Metalle","Indizes","Energien","Krypto","Rohstoffe","Aktien-CFDs"],"payout_methods":["Banküberweisung","Weitere im Client Area angezeigte Wege, je nach Verfügbarkeit"],"included_items":["MetaTrader 4, MetaTrader 5, cTrader und TradingView","FTMO-Dashboard und Performance-Kennzahlen","Keine Aktivierungsgebühr für das finanzierte Konto"],"pros":["Seit 2015 am Markt, einer der längsten Track Records der Branche","90 % Gewinnbeteiligung beim 1-Step, die höhere der beiden","Keine Zeitbegrenzung, weder beim 1-Step noch beim 2-Step","Der 1-Step schreibt keine feste Mindestanzahl an Handelstagen vor","Beim 2-Step wird die Gebühr mit der ersten Auszahlung vollständig erstattet","Das Swing-Konto hebt Nachrichten-, Nacht- und Wochenendbeschränkungen auf","Allokation bis 400.000 $, über den Scaling Plan bis 2.000.000 $","Preise in Euro, ab 79 €"],"cons":["Kein Reset: Nach einem Fehlversuch kauft man eine komplett neue Challenge","Die Gebührenerstattung wird beim 1-Step nicht zugesichert","Der 1-Step senkt das Tageslimit auf 3 % und nutzt einen nachlaufenden Drawdown","Der 2-Step verlangt 4 Handelstage in jeder Phase","Das finanzierte Standard-Konto beschränkt Nachrichten, Nacht- und Wochenendpositionen","Swing gibt es beim 1-Step nicht und begrenzt den Hebel auf 1:30","Swing bietet kein 200K-Konto"],"special_features":["Zwei Produkte mit wirklich unterschiedlichen Regeln","1-Step: 3 % Tagesverlust, nachlaufender Drawdown mit Fixierung am Startsaldo","2-Step: 5 % Tagesverlust, fixer Drawdown","Die Best-Day-Regel gilt nur beim 1-Step","Hebel bis 1:100 bei Standard, 1:30 bei Swing","Scaling Plan: +25 % Saldo alle 4 Monate, nur beim 2-Step","Kein Pflicht-Stop-Loss","Zahlung per Karte, Überweisung, PayPal, Skrill, Krypto und Revolut Pay; Apple Pay und Google Pay je nach Verfügbarkeit"],"verdict_card":{"title":"Für wen es passt — und für wen nicht","body":"FTMO verkauft zwei Produkte, die man vor dem Kauf auseinanderhalten sollte. Der 1-Step zahlt mehr — 90 % — und schreibt keinen Kalender vor, zieht die Zügel im Tagesgeschäft aber an. Der 2-Step zahlt 80 %, lässt täglich mehr Spielraum und erstattet die Gebühr mit der ersten Auszahlung.","points":["Die beste Beteiligung ohne Bedingungen: 90 % ab der ersten Auszahlung beim 1-Step","Die Gebühr zurückbekommen: Der 2-Step erstattet sie vollständig mit der ersten Auszahlung","Ein komfortables Tageslimit: 5 % beim 2-Step gegenüber 3 % beim 1-Step","Die Freiheit, Positionen über Nacht und über das Wochenende zu halten — mit Swing","Eine Allokation, die über den Scaling Plan 2.000.000 $ erreicht"]},"program_guide":{"title":"Drei Wege, drei Kompromisse","intro":"Alle drei führen zu einem finanzierten Konto. Entscheidend sind die Beteiligung, der Kalender und wie frei Sie Positionen halten dürfen.","options":[{"name":"1-Step","badge":"Eine Phase","summary":"Die höchste Beteiligung, 90 %, und keine Mindesttage. Dafür ein Tageslimit von 3 % und ein Drawdown, der Ihren Hochs folgt.","points":["10 % Ziel, 90 % Beteiligung","3 % Tagesverlust","Nachlaufender Drawdown, fixiert am Startsaldo","Bester Tag ≤ 50 % des Gewinns der Gewinntage","Von 79 € (10K) bis 999 € (200K)"]},{"name":"2-Step Standard","badge":"Zwei Phasen","summary":"10 % und dann 5 % Ziel, ein breiteres Tageslimit von 5 % und ein fixer Drawdown. Die Gebühr wird mit der ersten Auszahlung erstattet.","points":["10 % dann 5 % Ziel, 80 % Beteiligung","5 % Tagesverlust, fixer Drawdown","4 Mindesthandelstage je Phase","Gebühr zu 100 % bei der ersten Auszahlung erstattet","Von 89 € (10K) bis 1.080 € (200K)"]},{"name":"2-Step Swing","badge":"Positionen halten","summary":"Die Regeln des 2-Step, ohne jede Nachrichten-, Nacht- oder Wochenendbeschränkung, auch auf dem finanzierten Konto. Der Hebel sinkt auf 1:30 und ein 200K gibt es nicht.","points":["Gleiche Ziele und Limits wie beim 2-Step Standard","Nachrichten, Nacht und Wochenende frei, auch finanziert","Hebel auf 1:30 begrenzt","Von 99 € (10K) bis 599 € (100K)"]}]},"key_rules":{"title":"Die Regeln, die entscheiden","intro":"Fünf Punkte, die die meisten Vergleichsseiten falsch wiedergeben.","rules":[{"title":"Die Beteiligung hängt vom Produkt ab","detail":"90 % beim 1-Step, ohne Bedingung. 80 % beim 2-Step, über den Scaling Plan auf 90 %. Seiten, die pauschal „bis zu 90 %\" nennen, verschweigen, dass der 1-Step dort startet."},{"title":"Nur der 2-Step erstattet die Gebühr","detail":"Der 2-Step gibt 100 % des Challenge-Preises mit der ersten Auszahlung zurück. Beim 1-Step stellt FTMO keine Erstattung in Aussicht. Trotz niedrigerem Listenpreis kommt der 1-Step damit teurer, sobald Sie finanziert sind."},{"title":"Der Tagesverlust unterscheidet sich — und zählt auf Equity","detail":"3 % beim 1-Step, 5 % beim 2-Step. Gemessen wird auf die Equity — also inklusive schwebender Verluste, Kommissionen und Swaps — mit Rücksetzung um Mitternacht CE(S)T, nicht in Ihrer Zeitzone."},{"title":"Der 1-Step-Drawdown läuft nach und friert dann ein","detail":"Er steigt mit Ihrem höchsten Schlusssaldo und bleibt endgültig stehen, sobald er den Startsaldo erreicht. Der 2-Step arbeitet vom ersten Trade an mit fixem Drawdown."},{"title":"Es gibt keinen Reset","detail":"Eine gescheiterte Challenge lässt sich nicht vergünstigt neu starten: Sie kaufen eine ganz neue. Das ist ein echter Kostenunterschied gegenüber Anbietern, die 50 % für einen Reset verlangen."}],"more":["Keine Zeitbegrenzung auf allen drei Wegen","Keine festen Mindesttage beim 1-Step; 4 je Phase beim 2-Step","Keine Aktivierungsgebühr für das finanzierte Konto","Kein Pflicht-Stop-Loss","Hebel bis 1:100 bei Standard, 1:30 bei Swing","Scaling Plan: +25 % Saldo alle 4 Monate, beim 2-Step","MT4, MT5, cTrader und TradingView"]},"journey":{"title":"Was nach der Zahlung passiert","intro":"Der Weg unterscheidet sich je nach Produkt.","steps":[{"title":"Evaluierung","detail":"Eine Phase beim 1-Step, zwei beim 2-Step. In dieser Phase gibt es keine Beschränkung für Nachrichten, Nacht- oder Wochenendpositionen, unabhängig vom Produkt."},{"title":"Verifizierung","detail":"Nur beim 2-Step: ein zweites Ziel von 5 %, unter denselben Risikolimits wie in der ersten Phase."},{"title":"FTMO-Konto","detail":"Standard beschränkt Nachrichten und verlangt das Schließen vor Marktpausen von über 2 Stunden und vor dem Wochenende. Swing beschränkt nichts. Swing gibt es beim 1-Step nicht."},{"title":"Auszahlungen","detail":"Die erste kann nicht vor 14 Tagen beantragt werden; danach wählen Sie Ihren Auszahlungstag. Beim 2-Step erstattet diese erste Auszahlung zugleich den Challenge-Preis."}]},"cost_timeline":{"title":"Was Sie zahlen werden","intro":"Die Kosten fallen nicht alle zum selben Zeitpunkt an — und ein Teil kommt zurück.","steps":[{"label":"Beim Kauf","title":"Einmalige Gebühr","detail":"Von 79 € für ein 1-Step 10K bis 1.080 € für ein 2-Step 200K. Kein Abonnement."},{"label":"Bei Nichtbestehen","title":"Kein Reset verfügbar","detail":"FTMO verkauft keine vergünstigten Resets: Neu anfangen heißt eine ganz neue Challenge kaufen."},{"label":"Beim Bestehen","title":"Keine Aktivierungsgebühr","detail":"Das finanzierte Konto wird ohne weitere Zahlung eröffnet."},{"label":"Bei der ersten Auszahlung","title":"Erstattung beim 2-Step","detail":"Der 2-Step gibt 100 % des Challenge-Preises mit der ersten Auszahlung zurück. Der 1-Step stellt keine Erstattung in Aussicht."}]}},"es":{"headquarters":"Quadrio Offices, Purkyňova 2121/3, 110 00 Praga, República Checa","regulation_details":"FTMO Evaluation Global s.r.o.; la entidad contratante puede variar según la región. Ni bróker ni empresa de inversión: el servicio funciona con cuentas simuladas y no acepta depósitos de clientes.","max_allocation":"Hasta 400.000 $ de asignación inicial y hasta 2.000.000 $ mediante el Scaling Plan","drawdown_type":"Pérdida diaria calculada sobre el equity y reiniciada a medianoche CE(S)T. El drawdown global es progresivo al cierre en el 1-Step y se bloquea al alcanzar el saldo inicial; es fijo en el 2-Step.","time_limit":"Sin límite de tiempo, en ambos productos","payout_frequency":"a petición, no antes de 14 días desde tu primera operación","assets":["CFD sobre forex","Metales","Índices","Energías","Cripto","Materias primas","CFD sobre acciones"],"payout_methods":["Transferencia bancaria","Otros métodos mostrados en el Área de Cliente, según disponibilidad"],"included_items":["MetaTrader 4, MetaTrader 5, cTrader y TradingView","Panel de FTMO y métricas de rendimiento","Sin comisión de activación de la cuenta financiada"],"pros":["En activo desde 2015, uno de los historiales más largos del sector","90 % de reparto en el 1-Step, el más alto de los dos productos","Sin límite de tiempo, ni en el 1-Step ni en el 2-Step","El 1-Step no impone un mínimo fijo de días de trading","En el 2-Step, la cuota se reembolsa al 100 % con el primer pago","La cuenta Swing levanta las restricciones de noticias, noche y fin de semana","Asignación hasta 400.000 $, y hasta 2.000.000 $ con el Scaling Plan","Precios en euros, desde 79 €"],"cons":["Sin reset: tras un fallo hay que comprar un challenge entero","El reembolso de la cuota no se anuncia en el 1-Step","El 1-Step aprieta el límite diario al 3 % y usa un drawdown progresivo","El 2-Step exige 4 días de trading en cada fase","La cuenta financiada Standard restringe noticias, noche y fin de semana","Swing no existe en el 1-Step y limita el apalancamiento a 1:30","Swing no ofrece cuenta de 200K"],"special_features":["Dos productos con reglas realmente distintas","1-Step: 3 % de pérdida diaria, drawdown progresivo bloqueado en el saldo inicial","2-Step: 5 % de pérdida diaria, drawdown fijo","La regla del mejor día solo se aplica al 1-Step","Apalancamiento hasta 1:100 en Standard, 1:30 en Swing","Scaling Plan: +25 % de saldo cada 4 meses, solo en el 2-Step","Sin stop-loss obligatorio","Pago con tarjeta, transferencia, PayPal, Skrill, cripto y Revolut Pay; Apple Pay y Google Pay según disponibilidad"],"verdict_card":{"title":"Para quién sí, y para quién no","body":"FTMO vende dos productos que conviene distinguir antes de comprar. El 1-Step paga más — 90 % — y no impone calendario, pero aprieta día a día. El 2-Step paga 80 %, deja más margen diario y devuelve la cuota con el primer pago.","points":["El mejor reparto sin condiciones: 90 % desde el primer pago en el 1-Step","Recuperar la cuota: el 2-Step la reembolsa al 100 % con el primer pago","Un límite diario cómodo: 5 % en el 2-Step frente al 3 % del 1-Step","La libertad de mantener posiciones de noche y el fin de semana, con Swing","Una asignación que llega a 2.000.000 $ con el Scaling Plan"]},"program_guide":{"title":"Tres caminos, tres compromisos","intro":"Los tres llevan a una cuenta financiada. La elección se juega en el reparto, el calendario y la libertad para mantener posiciones.","options":[{"name":"1-Step","badge":"Una sola fase","summary":"El reparto más alto, 90 %, y sin días mínimos. A cambio, un límite diario del 3 % y un drawdown que sigue tus máximos.","points":["Objetivo del 10 %, reparto del 90 %","3 % de pérdida diaria","Drawdown progresivo, bloqueado en el saldo inicial","Mejor día ≤ 50 % del beneficio de los días positivos","De 79 € (10K) a 999 € (200K)"]},{"name":"2-Step Standard","badge":"Dos fases","summary":"Objetivo del 10 % y luego del 5 %, un límite diario más amplio del 5 % y un drawdown fijo. La cuota se reembolsa con el primer pago.","points":["Objetivo 10 % luego 5 %, reparto del 80 %","5 % de pérdida diaria, drawdown fijo","4 días mínimos de trading por fase","Cuota reembolsada al 100 % en el primer pago","De 89 € (10K) a 1.080 € (200K)"]},{"name":"2-Step Swing","badge":"Mantener posiciones","summary":"Las reglas del 2-Step, sin restricción de noticias, noche ni fin de semana, cuenta financiada incluida. El apalancamiento baja a 1:30 y no hay 200K.","points":["Mismos objetivos y límites que el 2-Step Standard","Noticias, noche y fin de semana libres, incluso ya financiado","Apalancamiento limitado a 1:30","De 99 € (10K) a 599 € (100K)"]}]},"key_rules":{"title":"Las reglas que deciden","intro":"Cinco puntos que la mayoría de comparadores cuenta mal.","rules":[{"title":"El reparto depende del producto","detail":"90 % en el 1-Step, sin condiciones. 80 % en el 2-Step, hasta el 90 % con el Scaling Plan. Las páginas que anuncian «hasta 90 %» para toda la gama ocultan que el 1-Step ya empieza ahí."},{"title":"Solo el 2-Step reembolsa la cuota","detail":"El 2-Step devuelve el 100 % del precio del challenge con el primer pago. En el 1-Step, FTMO no anuncia reembolso. Con un precio de catálogo más bajo, el 1-Step sale por tanto más caro una vez financiado."},{"title":"La pérdida diaria difiere, y se mide sobre el equity","detail":"3 % en el 1-Step, 5 % en el 2-Step. Se mide sobre el equity — es decir, con pérdidas flotantes, comisiones y swaps incluidos — y se reinicia a medianoche CE(S)T, no en tu huso horario."},{"title":"El drawdown del 1-Step avanza y luego se bloquea","detail":"Sube con tu saldo de cierre más alto y se detiene definitivamente al alcanzar el saldo inicial. El 2-Step usa un drawdown fijo desde la primera operación."},{"title":"No existe ningún reset","detail":"Un challenge fallido no se reanuda con descuento: hay que comprar otro entero. Es una diferencia de coste real frente a las firmas que cobran el 50 % por un reset."}],"more":["Sin límite de tiempo en los tres caminos","Sin días mínimos fijos en el 1-Step; 4 por fase en el 2-Step","Sin comisión de activación de la cuenta financiada","Sin stop-loss obligatorio","Apalancamiento hasta 1:100 en Standard, 1:30 en Swing","Scaling Plan: +25 % de saldo cada 4 meses, en el 2-Step","MT4, MT5, cTrader y TradingView"]},"journey":{"title":"Qué ocurre después de pagar","intro":"El camino cambia según el producto.","steps":[{"title":"Evaluación","detail":"Una fase en el 1-Step, dos en el 2-Step. En esta etapa no hay restricción de noticias ni de posiciones nocturnas o de fin de semana, sea cual sea el producto."},{"title":"Verificación","detail":"Solo en el 2-Step: un segundo objetivo del 5 %, con los mismos límites de riesgo que la primera fase."},{"title":"Cuenta FTMO","detail":"Standard restringe las noticias y obliga a cerrar antes de pausas de mercado de más de 2 horas y antes del fin de semana. Swing no restringe nada. Swing no existe en el 1-Step."},{"title":"Pagos","detail":"El primero no puede solicitarse antes de 14 días; después eliges tu día de pago. En el 2-Step, ese primer pago también reembolsa el precio del challenge."}]},"cost_timeline":{"title":"Lo que vas a pagar","intro":"Los costes no llegan todos al mismo tiempo — y una parte vuelve.","steps":[{"label":"Al comprar","title":"Cuota única","detail":"De 79 € para un 1-Step 10K a 1.080 € para un 2-Step 200K. Sin suscripción."},{"label":"Si fallas","title":"Sin reset disponible","detail":"FTMO no vende resets con descuento: volver a empezar significa comprar un challenge entero."},{"label":"Al superarlo","title":"Sin comisión de activación","detail":"La cuenta financiada se abre sin ningún pago adicional."},{"label":"En el primer pago","title":"Reembolso en el 2-Step","detail":"El 2-Step devuelve el 100 % del precio del challenge con el primer pago. El 1-Step no anuncia reembolso."}]}},"pt":{"headquarters":"Quadrio Offices, Purkyňova 2121/3, 110 00 Praga, República Checa","regulation_details":"FTMO Evaluation Global s.r.o.; a entidade contratante pode variar consoante a região. Nem corretora nem empresa de investimento: o serviço assenta em contas simuladas e não aceita depósitos de clientes.","max_allocation":"Até 400 000 $ de alocação inicial e até 2 000 000 $ através do Scaling Plan","drawdown_type":"Perda diária calculada sobre o equity e reposta à meia-noite CE(S)T. O drawdown global é progressivo ao fecho no 1-Step e bloqueia ao atingir o saldo inicial; é fixo no 2-Step.","time_limit":"Sem limite de tempo, nos dois produtos","payout_frequency":"a pedido, no mínimo 14 dias após a primeira operação","assets":["CFD sobre forex","Metais","Índices","Energia","Cripto","Matérias-primas","CFD sobre ações"],"payout_methods":["Transferência bancária","Outros métodos apresentados na Área de Cliente, consoante a disponibilidade"],"included_items":["MetaTrader 4, MetaTrader 5, cTrader e TradingView","Painel FTMO e métricas de desempenho","Sem taxa de ativação da conta financiada"],"pros":["Em atividade desde 2015, um dos historiais mais longos do setor","90 % de partilha no 1-Step, a mais alta dos dois produtos","Sem limite de tempo, nem no 1-Step nem no 2-Step","O 1-Step não impõe um mínimo fixo de dias de negociação","No 2-Step, a taxa é reembolsada a 100 % com o primeiro pagamento","A conta Swing levanta as restrições de notícias, noite e fim de semana","Alocação até 400 000 $, e até 2 000 000 $ com o Scaling Plan","Preços em euros, a partir de 79 €"],"cons":["Sem reset: após uma falha é preciso comprar um challenge inteiro","O reembolso da taxa não é anunciado no 1-Step","O 1-Step aperta o limite diário para 3 % e usa um drawdown progressivo","O 2-Step exige 4 dias de negociação em cada fase","A conta financiada Standard restringe notícias, noite e fim de semana","O Swing não existe no 1-Step e limita a alavancagem a 1:30","O Swing não oferece conta de 200K"],"special_features":["Dois produtos com regras verdadeiramente diferentes","1-Step: 3 % de perda diária, drawdown progressivo bloqueado no saldo inicial","2-Step: 5 % de perda diária, drawdown fixo","A regra do melhor dia aplica-se apenas ao 1-Step","Alavancagem até 1:100 no Standard, 1:30 no Swing","Scaling Plan: +25 % de saldo a cada 4 meses, apenas no 2-Step","Sem stop-loss obrigatório","Pagamento por cartão, transferência, PayPal, Skrill, cripto e Revolut Pay; Apple Pay e Google Pay consoante a disponibilidade"],"verdict_card":{"title":"Para quem serve, e para quem não","body":"A FTMO vende dois produtos que convém distinguir antes de comprar. O 1-Step paga mais — 90 % — e não impõe calendário, mas aperta o dia a dia. O 2-Step paga 80 %, deixa mais margem diária e devolve a taxa com o primeiro pagamento.","points":["A melhor partilha sem condições: 90 % desde o primeiro pagamento no 1-Step","Recuperar a taxa: o 2-Step reembolsa-a a 100 % com o primeiro pagamento","Um limite diário confortável: 5 % no 2-Step contra 3 % no 1-Step","A liberdade de manter posições de noite e ao fim de semana, com o Swing","Uma alocação que chega a 2 000 000 $ com o Scaling Plan"]},"program_guide":{"title":"Três percursos, três compromissos","intro":"Os três levam a uma conta financiada. A escolha joga-se na partilha, no calendário e na liberdade de manter posições.","options":[{"name":"1-Step","badge":"Uma só fase","summary":"A partilha mais alta, 90 %, e sem dias mínimos. Em troca, um limite diário de 3 % e um drawdown que segue os seus máximos.","points":["Objetivo de 10 %, partilha de 90 %","3 % de perda diária","Drawdown progressivo, bloqueado no saldo inicial","Melhor dia ≤ 50 % do lucro dos dias positivos","De 79 € (10K) a 999 € (200K)"]},{"name":"2-Step Standard","badge":"Duas fases","summary":"Objetivo de 10 % e depois 5 %, um limite diário mais largo de 5 % e um drawdown fixo. A taxa é reembolsada com o primeiro pagamento.","points":["Objetivo 10 % depois 5 %, partilha de 80 %","5 % de perda diária, drawdown fixo","4 dias mínimos de negociação por fase","Taxa reembolsada a 100 % no primeiro pagamento","De 89 € (10K) a 1 080 € (200K)"]},{"name":"2-Step Swing","badge":"Manter posições","summary":"As regras do 2-Step, sem qualquer restrição de notícias, noite ou fim de semana, incluindo na conta financiada. A alavancagem desce para 1:30 e não há 200K.","points":["Mesmos objetivos e limites que o 2-Step Standard","Notícias, noite e fim de semana livres, mesmo já financiado","Alavancagem limitada a 1:30","De 99 € (10K) a 599 € (100K)"]}]},"key_rules":{"title":"As regras que decidem","intro":"Cinco pontos que a maioria dos comparadores conta mal.","rules":[{"title":"A partilha depende do produto","detail":"90 % no 1-Step, sem condições. 80 % no 2-Step, até 90 % através do Scaling Plan. As páginas que anunciam «até 90 %» para toda a gama escondem que o 1-Step já começa aí."},{"title":"Só o 2-Step reembolsa a taxa","detail":"O 2-Step devolve 100 % do preço do challenge com o primeiro pagamento. No 1-Step, a FTMO não anuncia reembolso. Com um preço de tabela mais baixo, o 1-Step sai portanto mais caro depois de financiado."},{"title":"A perda diária difere, e mede-se sobre o equity","detail":"3 % no 1-Step, 5 % no 2-Step. É medida sobre o equity — ou seja, incluindo perdas latentes, comissões e swaps — e repõe-se à meia-noite CE(S)T, não no seu fuso horário."},{"title":"O drawdown do 1-Step avança e depois bloqueia","detail":"Sobe com o seu saldo de fecho mais alto e para definitivamente ao atingir o saldo inicial. O 2-Step usa um drawdown fixo desde a primeira operação."},{"title":"Não existe qualquer reset","detail":"Um challenge falhado não se reinicia com desconto: é preciso comprar outro inteiro. É uma diferença de custo real face às firmas que cobram 50 % por um reset."}],"more":["Sem limite de tempo nos três percursos","Sem dias mínimos fixos no 1-Step; 4 por fase no 2-Step","Sem taxa de ativação da conta financiada","Sem stop-loss obrigatório","Alavancagem até 1:100 no Standard, 1:30 no Swing","Scaling Plan: +25 % de saldo a cada 4 meses, no 2-Step","MT4, MT5, cTrader e TradingView"]},"journey":{"title":"O que acontece depois do pagamento","intro":"O percurso muda consoante o produto.","steps":[{"title":"Avaliação","detail":"Uma fase no 1-Step, duas no 2-Step. Nesta etapa não há restrição de notícias nem de posições noturnas ou de fim de semana, qualquer que seja o produto."},{"title":"Verificação","detail":"Apenas no 2-Step: um segundo objetivo de 5 %, com os mesmos limites de risco da primeira fase."},{"title":"Conta FTMO","detail":"A Standard restringe as notícias e obriga a fechar antes de pausas de mercado superiores a 2 horas e antes do fim de semana. A Swing não restringe nada. A Swing não existe no 1-Step."},{"title":"Pagamentos","detail":"O primeiro não pode ser pedido antes de 14 dias; depois escolhe o seu dia de pagamento. No 2-Step, esse primeiro pagamento reembolsa também o preço do challenge."}]},"cost_timeline":{"title":"O que vai pagar","intro":"Os custos não chegam todos ao mesmo tempo — e parte volta.","steps":[{"label":"Na compra","title":"Taxa única","detail":"De 79 € para um 1-Step 10K a 1 080 € para um 2-Step 200K. Sem subscrição."},{"label":"Em caso de falha","title":"Sem reset disponível","detail":"A FTMO não vende resets com desconto: recomeçar significa comprar um challenge inteiro."},{"label":"Ao passar","title":"Sem taxa de ativação","detail":"A conta financiada abre sem qualquer pagamento adicional."},{"label":"No primeiro pagamento","title":"Reembolso no 2-Step","detail":"O 2-Step devolve 100 % do preço do challenge com o primeiro pagamento. O 1-Step não anuncia reembolso."}]}},"ar":{"headquarters":"Quadrio Offices، Purkyňova 2121/3، 110 00 براغ، التشيك","regulation_details":"FTMO Evaluation Global s.r.o.؛ قد تختلف الجهة المتعاقدة حسب المنطقة. ليست وسيطًا ولا شركة استثمار: تعمل الخدمة على حسابات محاكاة ولا تقبل أي إيداع من العملاء.","max_allocation":"حتى 400,000 $ كتخصيص أولي، وحتى 2,000,000 $ عبر خطة التوسّع","drawdown_type":"تُحسب الخسارة اليومية على أساس حقوق الملكية وتُصفَّر عند منتصف الليل بتوقيت وسط أوروبا. التراجع الإجمالي متحرك في نهاية اليوم في برنامج الخطوة الواحدة ويتوقف عند بلوغ الرصيد الابتدائي؛ وهو ثابت في برنامج الخطوتين.","time_limit":"بلا حد زمني، في كلا المنتجين","payout_frequency":"عند الطلب، بعد 14 يومًا على الأقل من أول صفقة","assets":["عقود فروقات على الفوركس","المعادن","المؤشرات","الطاقة","العملات الرقمية","السلع","عقود فروقات على الأسهم"],"payout_methods":["تحويل بنكي","وسائل أخرى تظهر في منطقة العميل، حسب التوفّر"],"included_items":["MetaTrader 4 وMetaTrader 5 وcTrader وTradingView","لوحة تحكم FTMO ومؤشرات الأداء","لا رسوم تفعيل للحساب المموَّل"],"pros":["نشطة منذ 2015، وأحد أطول السجلات في القطاع","تقاسم بنسبة 90 % في برنامج الخطوة الواحدة، وهو الأعلى بين المنتجين","بلا حد زمني، لا في الخطوة الواحدة ولا في الخطوتين","برنامج الخطوة الواحدة لا يفرض حدًا أدنى ثابتًا من أيام التداول","في برنامج الخطوتين تُسترد الرسوم بالكامل مع أول مكافأة","حساب Swing يرفع قيود الأخبار والمبيت وعطلة نهاية الأسبوع","تخصيص حتى 400,000 $، وحتى 2,000,000 $ عبر خطة التوسّع","الأسعار باليورو، ابتداءً من 79 €"],"cons":["لا إعادة تعيين: بعد الإخفاق يجب شراء تحدٍّ كامل من جديد","استرداد الرسوم غير معلن في برنامج الخطوة الواحدة","برنامج الخطوة الواحدة يشدّ الحد اليومي إلى 3 % ويستخدم تراجعًا متحركًا","برنامج الخطوتين يتطلب 4 أيام تداول في كل مرحلة","الحساب المموَّل Standard يقيّد الأخبار والمبيت وعطلة نهاية الأسبوع","Swing غير متاح في الخطوة الواحدة ويحدّ الرافعة عند 1:30","Swing لا يوفّر حسابًا بحجم 200K"],"special_features":["منتجان بقواعد مختلفة فعليًا","الخطوة الواحدة: خسارة يومية 3 %، وتراجع متحرك يتوقف عند الرصيد الابتدائي","الخطوتان: خسارة يومية 5 %، وتراجع ثابت","قاعدة أفضل يوم تنطبق على برنامج الخطوة الواحدة فقط","رافعة حتى 1:100 في Standard، و1:30 في Swing","خطة التوسّع: +25 % من الرصيد كل 4 أشهر، في برنامج الخطوتين فقط","لا يُشترط وقف خسارة","الدفع بالبطاقة والتحويل وPayPal وSkrill والعملات الرقمية وRevolut Pay؛ وApple Pay وGoogle Pay حسب التوفّر"],"verdict_card":{"title":"لمن تناسب، ولمن لا","body":"تبيع FTMO منتجين ينبغي التمييز بينهما قبل الشراء. برنامج الخطوة الواحدة يدفع أكثر — 90 % — ولا يفرض جدولًا زمنيًا، لكنه يشدّ الخناق يوميًا. برنامج الخطوتين يدفع 80 %، ويترك هامشًا يوميًا أوسع، ويعيد الرسوم مع أول مكافأة.","points":["أفضل نسبة تقاسم بلا شروط: 90 % من أول مكافأة في الخطوة الواحدة","استعادة الرسوم: برنامج الخطوتين يعيدها بالكامل مع أول مكافأة","حد يومي مريح: 5 % في الخطوتين مقابل 3 % في الخطوة الواحدة","حرية الاحتفاظ بالصفقات ليلًا وفي عطلة نهاية الأسبوع، مع حساب Swing","تخصيص يصل إلى 2,000,000 $ عبر خطة التوسّع"]},"program_guide":{"title":"ثلاثة مسارات، ثلاث مقايضات","intro":"الثلاثة تؤدي إلى حساب مموَّل. الفارق في نسبة التقاسم والجدول الزمني وحرية الاحتفاظ بالصفقات.","options":[{"name":"خطوة واحدة","badge":"مرحلة واحدة","summary":"أعلى نسبة تقاسم، 90 %، وبلا أيام دنيا. في المقابل حد يومي 3 % وتراجع يتبع أعلى نقاطك.","points":["هدف 10 %، تقاسم 90 %","خسارة يومية 3 %","تراجع متحرك يتوقف عند الرصيد الابتدائي","أفضل يوم ≤ 50 % من ربح الأيام الرابحة","من 79 € (10K) إلى 999 € (200K)"]},{"name":"خطوتان Standard","badge":"مرحلتان","summary":"هدف 10 % ثم 5 %، وحد يومي أوسع عند 5 %، وتراجع ثابت. تُسترد الرسوم مع أول مكافأة.","points":["هدف 10 % ثم 5 %، تقاسم 80 %","خسارة يومية 5 %، تراجع ثابت","4 أيام تداول كحد أدنى لكل مرحلة","استرداد كامل للرسوم عند أول مكافأة","من 89 € (10K) إلى 1,080 € (200K)"]},{"name":"خطوتان Swing","badge":"الاحتفاظ بالصفقات","summary":"قواعد برنامج الخطوتين، دون أي قيد على الأخبار أو المبيت أو عطلة نهاية الأسبوع، حتى على الحساب المموَّل. تنخفض الرافعة إلى 1:30 ولا يوجد حساب 200K.","points":["الأهداف والحدود نفسها كما في Standard","الأخبار والمبيت وعطلة نهاية الأسبوع بحرية، حتى بعد التمويل","الرافعة محدودة عند 1:30","من 99 € (10K) إلى 599 € (100K)"]}]},"key_rules":{"title":"القواعد التي تحسم الاختيار","intro":"خمس نقاط تخطئ فيها معظم مواقع المقارنة.","rules":[{"title":"نسبة التقاسم تعتمد على المنتج","detail":"90 % في برنامج الخطوة الواحدة، دون شرط. و80 % في برنامج الخطوتين، ترتفع إلى 90 % عبر خطة التوسّع. الصفحات التي تعلن «حتى 90 %» للمجموعة كلها تُخفي أن برنامج الخطوة الواحدة يبدأ عندها."},{"title":"برنامج الخطوتين وحده يعيد الرسوم","detail":"يعيد برنامج الخطوتين 100 % من سعر التحدي مع أول مكافأة. أما برنامج الخطوة الواحدة فلا تعلن FTMO أي استرداد له. ورغم سعره المعلن الأدنى، يصبح بذلك أغلى بعد التمويل."},{"title":"الخسارة اليومية تختلف، وتُحسب على حقوق الملكية","detail":"3 % في الخطوة الواحدة و5 % في الخطوتين. تُحسب على حقوق الملكية — أي شاملة الخسائر العائمة والعمولات والفوائد — وتُصفَّر عند منتصف الليل بتوقيت وسط أوروبا، لا بتوقيتك."},{"title":"تراجع الخطوة الواحدة يتحرك ثم يثبت","detail":"يرتفع مع أعلى رصيد إغلاق لك، ثم يتوقف نهائيًا عند بلوغ الرصيد الابتدائي. أما برنامج الخطوتين فيعمل بتراجع ثابت منذ أول صفقة."},{"title":"لا توجد إعادة تعيين","detail":"التحدي الفاشل لا يُستأنف بسعر مخفّض: عليك شراء تحدٍّ كامل جديد. وهذا فارق تكلفة حقيقي مقابل شركات تطلب 50 % لإعادة التعيين."}],"more":["بلا حد زمني في المسارات الثلاثة","لا أيام دنيا ثابتة في الخطوة الواحدة؛ و4 أيام لكل مرحلة في الخطوتين","لا رسوم تفعيل للحساب المموَّل","لا يُشترط وقف خسارة","رافعة حتى 1:100 في Standard، و1:30 في Swing","خطة التوسّع: +25 % من الرصيد كل 4 أشهر، في برنامج الخطوتين","MT4 وMT5 وcTrader وTradingView"]},"journey":{"title":"ما يحدث بعد الدفع","intro":"يختلف المسار حسب المنتج المختار.","steps":[{"title":"التقييم","detail":"مرحلة واحدة في الخطوة الواحدة، ومرحلتان في الخطوتين. لا قيود على الأخبار أو المبيت أو عطلة نهاية الأسبوع في هذه المرحلة، أيًّا كان المنتج."},{"title":"التحقق","detail":"في برنامج الخطوتين فقط: هدف ثانٍ بنسبة 5 %، بالحدود نفسها للمخاطر كما في المرحلة الأولى."},{"title":"حساب FTMO","detail":"يقيّد Standard الأخبار ويلزم بالإغلاق قبل توقّف السوق لأكثر من ساعتين وقبل عطلة نهاية الأسبوع. أما Swing فلا يقيّد شيئًا. وSwing غير متاح في برنامج الخطوة الواحدة."},{"title":"المكافآت","detail":"لا يمكن طلب الأولى قبل 14 يومًا؛ بعدها تختار يوم المكافأة. وفي برنامج الخطوتين، تعيد هذه المكافأة الأولى سعر التحدي أيضًا."}]},"cost_timeline":{"title":"ما ستدفعه","intro":"التكاليف لا تأتي كلها في اللحظة نفسها — وجزء منها يعود إليك.","steps":[{"label":"عند الشراء","title":"رسوم لمرة واحدة","detail":"من 79 € لحساب 10K بخطوة واحدة إلى 1,080 € لحساب 200K بخطوتين. بلا اشتراك."},{"label":"عند الإخفاق","title":"لا إعادة تعيين","detail":"لا تبيع FTMO إعادة تعيين مخفّضة: البدء من جديد يعني شراء تحدٍّ كامل."},{"label":"عند النجاح","title":"لا رسوم تفعيل","detail":"يُفتح الحساب المموَّل دون أي دفعة إضافية."},{"label":"عند أول مكافأة","title":"استرداد في برنامج الخطوتين","detail":"يعيد برنامج الخطوتين 100 % من سعر التحدي مع أول مكافأة. أما الخطوة الواحدة فلا تعلن أي استرداد."}]}},"hi":{"headquarters":"Quadrio Offices, Purkyňova 2121/3, 110 00 प्राग, चेक गणराज्य","regulation_details":"FTMO Evaluation Global s.r.o.; अनुबंध करने वाली इकाई क्षेत्र के अनुसार बदल सकती है। न ब्रोकर, न निवेश फ़र्म: सेवा सिम्युलेटेड खातों पर चलती है और ग्राहकों से कोई जमा स्वीकार नहीं करती।","max_allocation":"4,00,000 $ तक की आरंभिक आवंटन राशि, और स्केलिंग प्लान के ज़रिए 20,00,000 $ तक","drawdown_type":"दैनिक हानि इक्विटी पर मापी जाती है और मध्यरात्रि CE(S)T पर रीसेट होती है। कुल ड्रॉडाउन 1-Step में दिन के अंत में आगे बढ़ता है और आरंभिक बैलेंस पर पहुँचकर रुक जाता है; 2-Step में यह स्थिर रहता है।","time_limit":"कोई समय-सीमा नहीं, दोनों उत्पादों में","payout_frequency":"अनुरोध पर, पहली ट्रेड के कम से कम 14 दिन बाद","assets":["फ़ॉरेक्स CFD","धातुएँ","सूचकांक","ऊर्जा","क्रिप्टो","कमोडिटी","स्टॉक CFD"],"payout_methods":["बैंक ट्रांसफ़र","क्लाइंट एरिया में दिखाए गए अन्य विकल्प, उपलब्धता के अनुसार"],"included_items":["MetaTrader 4, MetaTrader 5, cTrader और TradingView","FTMO डैशबोर्ड और प्रदर्शन मेट्रिक्स","फ़ंडेड खाते पर कोई सक्रियण शुल्क नहीं"],"pros":["2015 से सक्रिय, इस क्षेत्र के सबसे लंबे ट्रैक रिकॉर्ड में से एक","1-Step पर 90 % हिस्सेदारी, दोनों उत्पादों में सबसे अधिक","कोई समय-सीमा नहीं, न 1-Step में न 2-Step में","1-Step किसी निश्चित न्यूनतम ट्रेडिंग दिवस की माँग नहीं करता","2-Step में शुल्क पहली पेआउट के साथ पूरा वापस मिलता है","Swing खाता समाचार, रातभर और सप्ताहांत की पाबंदियाँ हटा देता है","आवंटन 4,00,000 $ तक, और स्केलिंग प्लान से 20,00,000 $ तक","कीमतें यूरो में, 79 € से शुरू"],"cons":["कोई रीसेट नहीं: असफलता के बाद पूरा नया चैलेंज खरीदना पड़ता है","1-Step पर शुल्क वापसी की घोषणा नहीं है","1-Step दैनिक सीमा घटाकर 3 % करता है और चलायमान ड्रॉडाउन रखता है","2-Step हर चरण में 4 ट्रेडिंग दिवस माँगता है","फ़ंडेड Standard खाता समाचार, रात और सप्ताहांत पर पाबंदी लगाता है","Swing 1-Step में उपलब्ध नहीं और लीवरेज 1:30 तक सीमित करता है","Swing में 200K खाता नहीं है"],"special_features":["दो उत्पाद, वास्तव में अलग नियमों के साथ","1-Step: 3 % दैनिक हानि, आरंभिक बैलेंस पर रुकने वाला चलायमान ड्रॉडाउन","2-Step: 5 % दैनिक हानि, स्थिर ड्रॉडाउन","बेस्ट-डे नियम केवल 1-Step पर लागू","लीवरेज Standard में 1:100 तक, Swing में 1:30","स्केलिंग प्लान: हर 4 महीने में +25 % बैलेंस, केवल 2-Step पर","स्टॉप-लॉस अनिवार्य नहीं","कार्ड, बैंक ट्रांसफ़र, PayPal, Skrill, क्रिप्टो और Revolut Pay से भुगतान; Apple Pay और Google Pay उपलब्धता के अनुसार"],"verdict_card":{"title":"किसके लिए उपयुक्त, और किसके लिए नहीं","body":"FTMO दो उत्पाद बेचता है जिन्हें खरीदने से पहले अलग-अलग समझना चाहिए। 1-Step अधिक देता है — 90 % — और कोई कैलेंडर नहीं थोपता, पर रोज़मर्रा में सख़्त है। 2-Step 80 % देता है, हर दिन ज़्यादा गुंजाइश छोड़ता है, और पहली पेआउट के साथ शुल्क लौटा देता है।","points":["बिना शर्त सबसे अच्छी हिस्सेदारी: 1-Step पर पहली पेआउट से ही 90 %","शुल्क वापस पाना: 2-Step इसे पहली पेआउट के साथ पूरा लौटाता है","आरामदायक दैनिक सीमा: 2-Step में 5 %, 1-Step में 3 %","रातभर और सप्ताहांत पोज़िशन रखने की आज़ादी, Swing के साथ","स्केलिंग प्लान से 20,00,000 $ तक पहुँचने वाला आवंटन"]},"program_guide":{"title":"तीन रास्ते, तीन समझौते","intro":"तीनों फ़ंडेड खाते तक ले जाते हैं। चुनाव हिस्सेदारी, कैलेंडर और पोज़िशन रखने की आज़ादी पर टिका है।","options":[{"name":"1-Step","badge":"एक ही चरण","summary":"सबसे ऊँची हिस्सेदारी, 90 %, और कोई न्यूनतम दिन नहीं। बदले में 3 % की दैनिक सीमा और आपके शिखरों का पीछा करता ड्रॉडाउन।","points":["10 % लक्ष्य, 90 % हिस्सेदारी","3 % दैनिक हानि","चलायमान ड्रॉडाउन, आरंभिक बैलेंस पर स्थिर","सर्वोत्तम दिन ≤ लाभ वाले दिनों के मुनाफ़े का 50 %","79 € (10K) से 999 € (200K) तक"]},{"name":"2-Step Standard","badge":"दो चरण","summary":"10 % फिर 5 % लक्ष्य, 5 % की व्यापक दैनिक सीमा और स्थिर ड्रॉडाउन। शुल्क पहली पेआउट के साथ लौटता है।","points":["10 % फिर 5 % लक्ष्य, 80 % हिस्सेदारी","5 % दैनिक हानि, स्थिर ड्रॉडाउन","हर चरण में कम से कम 4 ट्रेडिंग दिवस","पहली पेआउट पर शुल्क की 100 % वापसी","89 € (10K) से 1,080 € (200K) तक"]},{"name":"2-Step Swing","badge":"पोज़िशन रखना","summary":"2-Step के नियम, बिना किसी समाचार, रात या सप्ताहांत पाबंदी के — फ़ंडेड खाते पर भी। लीवरेज घटकर 1:30 और 200K उपलब्ध नहीं।","points":["2-Step Standard जैसे ही लक्ष्य और सीमाएँ","समाचार, रात और सप्ताहांत मुक्त, फ़ंडेड होने पर भी","लीवरेज 1:30 तक सीमित","99 € (10K) से 599 € (100K) तक"]}]},"key_rules":{"title":"निर्णायक नियम","intro":"पाँच बातें जिन्हें अधिकांश तुलना-साइटें ग़लत बताती हैं।","rules":[{"title":"हिस्सेदारी उत्पाद पर निर्भर है","detail":"1-Step पर 90 %, बिना शर्त। 2-Step पर 80 %, स्केलिंग प्लान से 90 % तक। जो पृष्ठ पूरी शृंखला के लिए «90 % तक» कहते हैं, वे छिपा जाते हैं कि 1-Step वहीं से शुरू होता है।"},{"title":"शुल्क केवल 2-Step में लौटता है","detail":"2-Step पहली पेआउट के साथ चैलेंज की पूरी क़ीमत लौटा देता है। 1-Step पर FTMO किसी वापसी की घोषणा नहीं करता। सूची-मूल्य कम होने के बावजूद, फ़ंडेड होने के बाद 1-Step इसलिए महँगा पड़ता है।"},{"title":"दैनिक हानि अलग है, और इक्विटी पर मापी जाती है","detail":"1-Step में 3 %, 2-Step में 5 %। यह इक्विटी पर मापी जाती है — यानी अस्थायी हानि, कमीशन और स्वैप सहित — और मध्यरात्रि CE(S)T पर रीसेट होती है, आपके समय-क्षेत्र में नहीं।"},{"title":"1-Step का ड्रॉडाउन चलता है, फिर रुक जाता है","detail":"यह आपके सबसे ऊँचे क्लोज़िंग बैलेंस के साथ बढ़ता है, और आरंभिक बैलेंस पर पहुँचकर स्थायी रूप से रुक जाता है। 2-Step पहली ट्रेड से ही स्थिर ड्रॉडाउन पर चलता है।"},{"title":"कोई रीसेट मौजूद नहीं","detail":"असफल चैलेंज छूट पर दोबारा शुरू नहीं होता: पूरा नया खरीदना पड़ता है। रीसेट के लिए 50 % लेने वाली फ़र्मों की तुलना में यह वास्तविक लागत-अंतर है।"}],"more":["तीनों रास्तों पर कोई समय-सीमा नहीं","1-Step में कोई निश्चित न्यूनतम दिन नहीं; 2-Step में हर चरण 4 दिन","फ़ंडेड खाते पर कोई सक्रियण शुल्क नहीं","स्टॉप-लॉस अनिवार्य नहीं","लीवरेज Standard में 1:100 तक, Swing में 1:30","स्केलिंग प्लान: हर 4 महीने में +25 % बैलेंस, 2-Step पर","MT4, MT5, cTrader और TradingView"]},"journey":{"title":"भुगतान के बाद क्या होता है","intro":"रास्ता चुने गए उत्पाद पर निर्भर है।","steps":[{"title":"मूल्यांकन","detail":"1-Step में एक चरण, 2-Step में दो। इस चरण में समाचार, रातभर या सप्ताहांत पोज़िशन पर कोई पाबंदी नहीं, उत्पाद चाहे जो हो।"},{"title":"सत्यापन","detail":"केवल 2-Step में: 5 % का दूसरा लक्ष्य, पहले चरण जैसी ही जोखिम सीमाओं के साथ।"},{"title":"FTMO खाता","detail":"Standard समाचार पर पाबंदी लगाता है और 2 घंटे से लंबे बाज़ार-अवकाश तथा सप्ताहांत से पहले पोज़िशन बंद करने को कहता है। Swing कुछ भी सीमित नहीं करता। Swing 1-Step में उपलब्ध नहीं।"},{"title":"पेआउट","detail":"पहली पेआउट 14 दिन से पहले नहीं माँगी जा सकती; उसके बाद आप अपना पेआउट दिवस चुनते हैं। 2-Step में यही पहली पेआउट चैलेंज की क़ीमत भी लौटा देती है।"}]},"cost_timeline":{"title":"आप क्या चुकाएँगे","intro":"सारी लागतें एक ही समय नहीं आतीं — और एक हिस्सा वापस आता है।","steps":[{"label":"ख़रीद पर","title":"एकमुश्त शुल्क","detail":"1-Step 10K के लिए 79 € से 2-Step 200K के लिए 1,080 € तक। कोई सदस्यता नहीं।"},{"label":"असफल होने पर","title":"कोई रीसेट उपलब्ध नहीं","detail":"FTMO छूट वाला रीसेट नहीं बेचता: दोबारा शुरू करने का अर्थ है पूरा नया चैलेंज खरीदना।"},{"label":"सफल होने पर","title":"कोई सक्रियण शुल्क नहीं","detail":"फ़ंडेड खाता बिना किसी अतिरिक्त भुगतान के खुलता है।"},{"label":"प